const mainNew = prev!;
console.log("main tree ok:", billingTree(all[all.length - 1]) === S(["rev-parse", `${mainNew}^{tree}`]));

function findTarget(T: string): { sha: string; hops: number } {
  if (map.has(T)) return { sha: map.get(T)!, hops: 0 };
  const tt = billingTree(T);
  const queue: [string, number][] = [[T, 0]];
  const seen = new Set([T]);
  while (queue.length) {
    const [c, d] = queue.shift()!;
    if (c !== T && map.has(c) && billingTree(c) === tt) return { sha: map.get(c)!, hops: d };
    for (const p of parentsOf(c)) if (!seen.has(p)) { seen.add(p); queue.push([p, d + 1]); }
